const msg = $input.first().json.message || {};
const chatId = msg.chat?.id;
const TOKEN = 'YOUR_TELEGRAM_BOT_TOKEN';

let type = 'text';
let text = msg.text || msg.caption || '';
let mediaBase64 = null;
let mimeType = null;
let fileId = null;

if (msg.photo && msg.photo.length) {
  type = 'photo';
  fileId = msg.photo[msg.photo.length - 1].file_id;
  mimeType = 'image/jpeg';
} else if (msg.voice) {
  type = 'voice';
  fileId = msg.voice.file_id;
  mimeType = msg.voice.mime_type || 'audio/ogg';
} else if (msg.audio) {
  type = 'voice';
  fileId = msg.audio.file_id;
  mimeType = msg.audio.mime_type || 'audio/mpeg';
} else if (msg.document) {
  type = 'photo';
  fileId = msg.document.file_id;
  mimeType = msg.document.mime_type || 'image/jpeg';
}

if (fileId) {
  const r = await fetch(`https://api.telegram.org/bot${TOKEN}/getFile?file_id=${fileId}`);
  const j = await r.json();
  const filePath = j.result?.file_path;
  if (filePath) {
    const fr = await fetch(`https://api.telegram.org/file/bot${TOKEN}/${filePath}`);
    const ab = await fr.arrayBuffer();
    mediaBase64 = Buffer.from(ab).toString('base64');
  }
}

if (!text && !mediaBase64) return [];

return [{ json: { type, text, mediaBase64, mimeType, chatId } }];

